import type { UsbDmxConfig, SerialPortInfo, DmxOutputStatus } from '../shared/types'
import { sourceUniverseProblem } from './output-config'
import { OutputHealth } from './output-health'
import { Mutex } from './async-mutex'

/**
 * USB DMX Output - supports multiple cheap USB-DMX adapters:
 *
 * 1. ENTTEC Open DMX USB / Eurolite / clones (FTDI-based, ~30EUR)
 *    - Simple serial at 250kbaud, sends raw DMX frames
 *    - BREAK generated by switching baud rate momentarily
 *    - No buffer on the adapter: the host must stream frames continuously
 *      (~30-44 Hz) or fixtures lose signal, so we send on EVERY tick.
 *
 * 2. ENTTEC DMX USB Pro (~150EUR)
 *    - Uses ENTTEC Pro protocol with message framing
 *    - The widget keeps refreshing the last frame itself: we send on change
 *      plus a keep-alive every second.
 *
 * Note: the Eurolite USB-DMX512 PRO has an internal microcontroller and
 * speaks the ENTTEC Pro protocol (as in QLC+); the plain Eurolite USB-DMX512
 * is FTDI-based Open DMX.
 *
 * Outputs are keyed by config id (two adapters may share a universe).
 * Unplug / write errors are detected through the port's 'error'/'close'
 * events and a write watchdog; the adapter is then re-opened with backoff,
 * found again by serial number if its path changed.
 */

const PRO_KEEPALIVE_MS = 1000
/** A frame that takes longer than this means the adapter stopped responding */
const WRITE_TIMEOUT_MS = 1000
const RECONNECT_DELAYS_MS = [1000, 2000, 5000, 10000]

interface UsbDmxInstance {
  id: string
  config: UsbDmxConfig
  configKey: string
  enabled: boolean
  invalid: string | null
  state: 'connecting' | 'ok' | 'error'
  /** Path actually opened (differs from config.portPath when found by serial number) */
  currentPath: string
  port: any | null // SerialPort instance
  buffer: Buffer
  sending: boolean // guard against concurrent writes
  sendStartedAt: number
  prev: Uint8Array
  hasPrev: boolean
  lastSentAt: number
  health: OutputHealth
  reconnectTimer: ReturnType<typeof setTimeout> | null
  reconnectAttempt: number
  /** Discarded by configure()/destroyAll(): every pending callback must give up */
  removed: boolean
}

/**
 * ENTTEC Pro protocol: message framing, the widget generates BREAK/MAB itself.
 * Open DMX protocol: raw frames at 250kbaud, host must generate BREAK.
 */
function isProProtocol(driver: string): boolean {
  return driver === 'enttec-pro' || driver === 'eurolite-pro'
}

export class UsbDmxOutput {
  private instances: UsbDmxInstance[] = []
  private SerialPort: any = null
  private available = false
  private lock = new Mutex()

  /** `SerialPort` can be injected (tests); otherwise the serialport module is loaded */
  constructor(private universeCount: number, opts: { SerialPort?: any } = {}) {
    if (opts.SerialPort) {
      this.SerialPort = opts.SerialPort
      this.available = true
      return
    }
    try {
      const sp = require('serialport')
      this.SerialPort = sp.SerialPort
      this.available = true
    } catch (e) {
      console.warn('[USB-DMX] serialport not available:', (e as Error).message)
      this.available = false
    }
  }

  /**
   * Scan for available serial ports (USB DMX adapters)
   */
  async scanPorts(): Promise<SerialPortInfo[]> {
    if (!this.available) return []
    try {
      const ports = await this.SerialPort.list()
      return ports.map((p: any) => ({
        path: p.path,
        manufacturer: p.manufacturer || undefined,
        serialNumber: p.serialNumber || undefined,
        vendorId: p.vendorId || undefined,
        productId: p.productId || undefined,
        friendlyName: p.friendlyName || p.pnpId || undefined
      }))
    } catch (e) {
      console.error('[USB-DMX] Failed to scan ports:', (e as Error).message)
      return []
    }
  }

  /**
   * Replace the USB outputs. Adapters whose config did not change keep their
   * open port (no glitch when another output type is reconfigured).
   * Serialised: concurrent calls never interleave port open/close.
   */
  configure(configs: UsbDmxConfig[]): Promise<void> {
    return this.lock.run(async () => {
      const next: UsbDmxInstance[] = []
      const keep = new Set<UsbDmxInstance>()

      configs.forEach((config, i) => {
        const id = config.id || `usb-${i + 1}`
        const configKey = JSON.stringify(config)
        const existing = this.instances.find(inst => inst.id === id && inst.configKey === configKey && !keep.has(inst))
        if (existing) {
          keep.add(existing)
          next.push(existing)
        } else {
          next.push(this.createInstance(id, config, configKey))
        }
      })

      // Close everything that is not kept BEFORE opening new ports (same path may be reused)
      for (const inst of this.instances) {
        if (!keep.has(inst)) await this.disposeInstance(inst)
      }
      this.instances = next

      if (!this.available && next.some(i => i.enabled)) {
        console.warn('[USB-DMX] serialport module not available — USB outputs cannot run')
      }

      for (const inst of next) {
        if (keep.has(inst) || !inst.enabled || inst.invalid || !this.available) continue
        await this.openInstance(inst)
      }
    })
  }

  private createInstance(id: string, config: UsbDmxConfig, configKey: string): UsbDmxInstance {
    const pro = isProProtocol(config.driver)
    return {
      id,
      config,
      configKey,
      enabled: config.enabled !== false,
      invalid: sourceUniverseProblem(config.universe, this.universeCount),
      state: 'connecting',
      currentPath: config.portPath,
      port: null,
      // Pro frame: header(1) + label(1) + length(2) + start_code(1) + 512ch + footer(1) = 518
      // Open DMX: start code (0x00) + 512 channels = 513
      buffer: Buffer.alloc(pro ? 518 : 513),
      sending: false,
      sendStartedAt: 0,
      prev: new Uint8Array(512),
      hasPrev: false,
      lastSentAt: 0,
      health: new OutputHealth(`USB ${config.label || config.portPath}`),
      reconnectTimer: null,
      reconnectAttempt: 0,
      removed: false
    }
  }

  /** Find the adapter: by serial number first (path can change on replug), then by path */
  private async resolvePath(inst: UsbDmxInstance): Promise<string | null> {
    let ports: any[]
    try {
      ports = await this.SerialPort.list()
    } catch {
      return inst.config.portPath // listing failed: just try the configured path
    }
    if (inst.config.serialNumber) {
      const bySerial = ports.find(p => p.serialNumber === inst.config.serialNumber)
      if (bySerial) return bySerial.path
    }
    if (ports.some(p => p.path === inst.config.portPath)) return inst.config.portPath
    return null
  }

  private async openInstance(inst: UsbDmxInstance): Promise<void> {
    if (inst.removed || inst.port) return
    inst.state = 'connecting'
    const path = await this.resolvePath(inst)
    if (inst.removed) return
    if (!path) {
      this.markFailed(inst, new Error(`Adapter not found on ${inst.config.portPath} (unplugged?)`))
      return
    }

    const pro = isProProtocol(inst.config.driver)
    const port = new this.SerialPort(pro
      ? { path, baudRate: 57600, dataBits: 8, stopBits: 1, parity: 'none', autoOpen: false }
      : { path, baudRate: 250000, dataBits: 8, stopBits: 2, parity: 'none', autoOpen: false })

    // Listeners first: an unplug can happen at any time
    port.on('error', (err: Error) => this.handlePortFailure(inst, port, err))
    port.on('close', (err: Error | null) => {
      this.handlePortFailure(inst, port, err || new Error('Serial port closed (adapter unplugged?)'))
    })

    try {
      await new Promise<void>((resolve, reject) => {
        port.open((err: Error | null) => err ? reject(err) : resolve())
      })
      // Enable the RS-485 transceiver output by asserting RTS + DTR
      await new Promise<void>((resolve) => {
        port.set(pro ? { rts: true, dtr: true } : { rts: true, dtr: true, brk: false }, (err: Error | null) => {
          if (err) console.warn(`[USB-DMX] ${path}: failed to set RTS/DTR: ${err.message}`)
          resolve()
        })
      })
    } catch (e) {
      this.closeQuietly(port)
      this.markFailed(inst, e)
      return
    }

    if (inst.removed) {
      this.closeQuietly(port)
      return
    }
    inst.port = port
    inst.currentPath = path
    inst.state = 'ok'
    inst.sending = false
    inst.hasPrev = false // force a full frame right away
    inst.reconnectAttempt = 0
    inst.health.ok()
    console.log(`[USB-DMX] ${inst.config.driver} ready on ${path} (universe ${inst.config.universe})`)
  }

  private markFailed(inst: UsbDmxInstance, err: unknown): void {
    if (inst.removed) return
    inst.state = 'error'
    inst.health.fail(err, Date.now())
    this.scheduleReconnect(inst)
  }

  /** A port reported an error/close, or the watchdog fired */
  private handlePortFailure(inst: UsbDmxInstance, port: any, err: unknown): void {
    if (inst.removed || inst.port !== port) return // stale port, or deliberate close
    inst.port = null
    inst.sending = false
    this.closeQuietly(port)
    this.markFailed(inst, err)
  }

  private scheduleReconnect(inst: UsbDmxInstance): void {
    if (inst.removed || inst.reconnectTimer || !this.available) return
    const delay = RECONNECT_DELAYS_MS[Math.min(inst.reconnectAttempt, RECONNECT_DELAYS_MS.length - 1)]
    inst.reconnectAttempt++
    inst.reconnectTimer = setTimeout(() => {
      inst.reconnectTimer = null
      if (inst.removed) return
      this.lock.run(() => this.openInstance(inst)).catch((e) => this.markFailed(inst, e))
    }, delay)
  }

  private closeQuietly(port: any): void {
    try {
      port.removeAllListeners?.('error')
      port.removeAllListeners?.('close')
      port.on?.('error', () => { /* closing */ })
      if (port.isOpen) port.close(() => {})
    } catch { /* already closed */ }
  }

  private disposeInstance(inst: UsbDmxInstance): Promise<void> {
    inst.removed = true
    if (inst.reconnectTimer) { clearTimeout(inst.reconnectTimer); inst.reconnectTimer = null }
    const port = inst.port
    inst.port = null
    if (!port) return Promise.resolve()
    port.removeAllListeners?.('error')
    port.removeAllListeners?.('close')
    port.on?.('error', () => { /* closing */ })
    return new Promise<void>((resolve) => {
      try {
        if (!port.isOpen) { resolve(); return }
        const timer = setTimeout(resolve, 1000) // never block reconfiguration on a hung close
        port.close(() => { clearTimeout(timer); resolve() })
      } catch {
        resolve()
      }
    })
  }

  /**
   * Called on every engine tick (~40 Hz).
   */
  send(universes: Uint8Array[], now: number = Date.now()): void {
    for (const inst of this.instances) {
      if (inst.state !== 'ok' || !inst.port) continue
      if (inst.sending) {
        // Skip while the previous frame is still being written (one busy
        // adapter must not starve the others)
        if (now - inst.sendStartedAt > WRITE_TIMEOUT_MS) {
          this.handlePortFailure(inst, inst.port, new Error('Write timed out (adapter not responding)'))
        }
        continue
      }
      const data = universes[inst.config.universe]
      if (!data) continue

      const pro = isProProtocol(inst.config.driver)
      if (pro && inst.hasPrev && now - inst.lastSentAt < PRO_KEEPALIVE_MS && equalBytes(inst.prev, data)) continue

      inst.prev.set(data.subarray(0, 512))
      inst.hasPrev = true
      inst.lastSentAt = now
      inst.sending = true
      inst.sendStartedAt = now
      if (pro) {
        this.sendEnttecPro(inst, data)
      } else {
        this.sendOpenDmx(inst, data)
      }
    }
  }

  private frameDone(inst: UsbDmxInstance, port: any): void {
    if (inst.port !== port) return
    inst.sending = false
    inst.health.ok()
    inst.health.frameSent(Date.now())
  }

  /**
   * Send raw DMX frame (Open DMX / FTDI style)
   * BREAK generated via baud-rate switching (most reliable on macOS):
   *   1. Switch to 100000 baud → send 0x00 → produces ~100µs BREAK on wire
   *   2. Switch back to 250000 baud → send START_CODE + 512 channel bytes
   *
   * This is the same approach used by node-dmx and QLC+.
   */
  private sendOpenDmx(inst: UsbDmxInstance, data: Uint8Array): void {
    const port = inst.port
    const fail = (err: Error) => this.handlePortFailure(inst, port, err)
    try {
      inst.buffer[0] = 0x00 // DMX start code
      inst.buffer.set(data.subarray(0, 512), 1)

      // Step 1: Switch to low baud rate for BREAK generation
      // At 100000 baud, a 0x00 byte = 10 bits × 10µs = 100µs low = valid BREAK (≥88µs)
      port.update({ baudRate: 100000 }, (err: Error | null) => {
        if (inst.port !== port) return
        if (err) return fail(err)
        // Send the BREAK byte (0x00 at low baud = long low signal)
        port.write(Buffer.from([0x00]), (err2: Error | null) => {
          if (inst.port !== port) return
          if (err2) return fail(err2)
          port.drain((err3: Error | null) => {
            if (inst.port !== port) return
            if (err3) return fail(err3)
            // Step 2: Switch back to DMX baud rate and send frame
            port.update({ baudRate: 250000 }, (err4: Error | null) => {
              if (inst.port !== port) return
              if (err4) return fail(err4)
              // Send DMX frame: start code (0x00) + 512 channels
              port.write(inst.buffer, (err5: Error | null) => {
                if (inst.port !== port) return
                if (err5) return fail(err5)
                port.drain((err6: Error | null) => {
                  if (err6) return fail(err6)
                  this.frameDone(inst, port)
                })
              })
            })
          })
        })
      })
    } catch (e) {
      fail(e as Error)
    }
  }

  /**
   * Send ENTTEC Pro message frame
   * Label 6 = "Send DMX Packet"
   * The Pro hardware handles BREAK/MAB timing internally.
   */
  private sendEnttecPro(inst: UsbDmxInstance, data: Uint8Array): void {
    const port = inst.port
    const fail = (err: Error) => this.handlePortFailure(inst, port, err)
    try {
      const dataLength = 513 // start code + 512 channels
      const buf = inst.buffer

      buf[0] = 0x7E        // Start delimiter
      buf[1] = 6            // Label: Send DMX Packet
      buf[2] = dataLength & 0xFF        // Length LSB
      buf[3] = (dataLength >> 8) & 0xFF // Length MSB
      buf[4] = 0x00         // DMX start code
      buf.set(data.subarray(0, 512), 5)
      buf[517] = 0xE7       // End delimiter

      port.write(buf, (err: Error | null) => {
        if (inst.port !== port) return
        if (err) return fail(err)
        port.drain((err2: Error | null) => {
          if (err2) return fail(err2)
          this.frameDone(inst, port)
        })
      })
    } catch (e) {
      fail(e as Error)
    }
  }

  /** Mark every running adapter with an error we could not attribute precisely */
  noteError(err: unknown, now: number = Date.now()): void {
    for (const inst of this.instances) if (inst.enabled) inst.health.fail(err, now)
  }

  getStatuses(now: number = Date.now()): DmxOutputStatus[] {
    return this.instances.map(inst => {
      let state: DmxOutputStatus['state']
      if (!inst.enabled) state = 'disabled'
      else if (inst.invalid) state = 'invalid'
      else if (!this.available) state = 'error'
      else state = inst.state
      const lastError = inst.invalid ?? (!this.available ? 'USB support (serialport) is not available on this system' : inst.health.lastError)
      return {
        id: inst.id,
        type: 'usb-dmx' as const,
        label: inst.config.label || `${inst.config.driver} ${inst.currentPath}`,
        enabled: inst.enabled,
        sourceUniverse: inst.config.universe,
        target: inst.currentPath,
        state,
        connected: state === 'ok',
        lastError: lastError || undefined,
        lastErrorAt: inst.invalid ? undefined : inst.health.lastErrorAt,
        framesSent: inst.health.framesSent,
        fps: inst.health.getFps(now)
      }
    })
  }

  /** Legacy status shape */
  getStatus(): { available: boolean; outputs: { universe: number; driver: string; port: string; connected: boolean }[] } {
    return {
      available: this.available,
      outputs: this.instances.map(inst => ({
        universe: inst.config.universe,
        driver: inst.config.driver,
        port: inst.currentPath,
        connected: inst.state === 'ok' && !!inst.port
      }))
    }
  }

  /**
   * Close all ports
   */
  destroyAll(): Promise<void> {
    return this.lock.run(async () => {
      const all = this.instances
      this.instances = []
      await Promise.all(all.map(inst => this.disposeInstance(inst)))
    })
  }

  isAvailable(): boolean {
    return this.available
  }
}

function equalBytes(a: Uint8Array, b: Uint8Array): boolean {
  const n = Math.min(a.length, b.length, 512)
  for (let i = 0; i < n; i++) if (a[i] !== b[i]) return false
  return true
}
